def helper(x, i, history, buffer, arr):
    # Mutates history and buffer and returns an integer delta.
    # Rule 1: if the last history item equals x, append x*2 to history,
    #         append x to buffer, and return -x.
    if history and history[-1] == x:
        history.append(x * 2)
        buffer.append(x)
        return -x

    # Otherwise append x to history and decide based on future occurrences:
    history.append(x)
    if x in arr[i+1:]:
        # If buffer ends with x, remove that buffer item and return x*2;
        # otherwise append x to buffer and return x.
        if buffer and buffer[-1] == x:
            buffer.pop()
            return x * 2
        buffer.append(x)
        return x

    # If x does not appear later: if buffer is nonempty, remove and return
    # the negative of the oldest buffer item; otherwise return 0.
    if buffer:
        return -buffer.pop(0)
    return 0


def process(arr, k):
    history = []   # records appended history items (FIFO when popped)
    buffer = []    # auxiliary FIFO/LIFO mix used by helper
    total = 0
    i = 0
    while i < len(arr):
        x = arr[i]
        delta = helper(x, i, history, buffer, arr)
        total += delta

        # Skipping rule: if buffer currently ends with x, skip the next element
        if buffer and buffer[-1] == x:
            i += 2
        else:
            i += 1

        # If history grows beyond k, pop the oldest and subtract it from total.
        # If the popped value is even, subtract half (integer division); else subtract full value.
        if len(history) > k:
            y = history.pop(0)
            if y % 2 == 0:
                total -= (y // 2)
            else:
                total -= y
    return total
